SELECT
  CASE WHEN (CAST(SUBSTR("2023-03-01", 6, 2) AS INT64) = 2) THEN CASE WHEN ((((MOD(CAST(SUBSTR("2023-03-01", 1, 4) AS INT64), NULLIF(4, 0))) = 0) AND ((MOD(CAST(SUBSTR("2023-03-01", 1, 4) AS INT64), NULLIF(100, 0))) != 0)) OR ((MOD(CAST(SUBSTR("2023-03-01", 1, 4) AS INT64), NULLIF(400, 0))) = 0)) THEN 29 ELSE 28 END ELSE ARRAY[31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][OFFSET(((CAST(SUBSTR("2023-03-01", 6, 2) AS INT64)) - (1)))] END AS n;